select oe1_0.id,(select sum(oe2_0.total) from orders oe2_0 where oe2_0.id<=? and (oe2_0.status<>? or oe2_0.status is null) and oe2_0.status=oe1_0.status) from orders oe1_0 where oe1_0.id<=? order by 1
select oe1_0.id,(select sum(oe2_0.total) from orders oe2_0 where oe2_0.id<=? and (oe2_0.status<>? or oe2_0.status is null) and oe2_0.status=oe1_0.status) from orders oe1_0 where oe1_0.id<=? and (select sum(oe3_0.total) from orders oe3_0 where oe3_0.id<=? and (oe3_0.status<>? or oe3_0.status is null) and oe3_0.status=oe1_0.status)=? order by 1
select oe1_0.id,(select sum(oe2_0.total) from orders oe2_0 where oe2_0.id<=? and (oe2_0.status<>? or oe2_0.status is null) and oe2_0.status=oe1_0.status) from orders oe1_0 where oe1_0.id<=? and (select sum(oe3_0.total) from orders oe3_0 where oe3_0.id<=? and (oe3_0.status<>? or oe3_0.status is null) and oe3_0.status=oe1_0.status) is null order by 1
select oe1_0.id,(select sum(oe2_0.referrer_id) from orders oe2_0 where oe2_0.id<=? and (oe2_0.status<>? or oe2_0.status is null) and oe2_0.status=oe1_0.status) from orders oe1_0 where oe1_0.id<=? order by 1
select oe1_0.id,(select sum(oe2_0.total) from orders oe2_0 where oe2_0.id<=? and (oe2_0.status<>? or oe2_0.status is null) and oe2_0.status=oe1_0.status) from orders oe1_0 where oe1_0.id<=? and (select sum(oe3_0.total) from orders oe3_0 where oe3_0.id<=? and (oe3_0.status<>? or oe3_0.status is null) and oe3_0.status=oe1_0.status) is not null order by 2,1
